def main():
    import html
    libs=json.loads(gzip.decompress(base64.b64decode(LIBRARIES)))
    imports={k:'data:text/javascript;base64,'+base64.b64encode(v.encode()).decode() for k,v in libs.items()}
    glb=build_glb()
    page=HTML.replace('__IMPORTMAP__',json.dumps({'imports':imports}))
    page=page.replace('__MODEL__',base64.b64encode(glb).decode())
    page=page.replace('__ASSUMPTIONS__',''.join('<p>'+html.escape(s)+'</p>' for s in ASSUMPTIONS))
    page=page.replace('__LICENSE_TEXT__',html.escape(THREE_LICENSE))
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / 'bathroom.glb').write_bytes(glb)
    (OUT / 'index.html').write_text(page, encoding='utf-8')
    print(f'{len(NODES)} meshes; {len(glb):,} bytes GLB; {len(page):,} characters HTML')
    print('GLB SHA-256:',hashlib.sha256(glb).hexdigest())
    print('HTML SHA-256:',hashlib.sha256(page.encode()).hexdigest())


if __name__=='__main__':
    main()
